```javascript
function isPrime(num) {
    if (num <= 1) return false; // Zahlen kleiner oder gleich 1 sind keine Primzahlen
    if (num === 2) return true; // 2 ist die kleinste Primzahl
    if (num % 2 === 0) return false; // Andere gerade Zahlen sind keine Primzahlen

    const sqrtNum = Math.sqrt(num);
    for (let i = 3; i <= sqrtNum; i += 2) {
        if (num % i === 0) return false;
    }
    return true;
}

function findPrimeNumbers(numbers) {
    if (numbers.length !== 5) {
        console.log("Bitte geben Sie genau 5 Zahlen ein.");
        return;
    }

    let foundPrime = false;
    for (let number of numbers) {
        if (isPrime(number)) {
            console.log(`Primzahl gefunden: ${number}`);
            foundPrime = true;
        }
    }

    if (!foundPrime) {
        console.log("Keine Primzahlen im Array gefunden.");
    }
}

// Beispielaufruf der Funktion
findPrimeNumbers([11, 18, 20, 22, 29]);
```

### Erklärung:
1. **isPrime(num)**: Diese Hilfsfunktion prüft, ob eine gegebene Zahl `num` eine Primzahl ist. Sie verwendet effiziente Prüfungen, um unnötige Berechnungen zu vermeiden.
